async function (
    triggerType, triggerData, reactorToken, item, activationName, api
) {
    if (!api.inDangerZone(reactorToken)) {
        ui.notifications.error(
        "BIFURCATE requires the ENKIDU to be in the Danger Zone."
    );
    return;
    };
    const selection = await api.chooseToken(reactorToken, {
        title: "BIFURCATE",
        range: 1,
        includeSelf: false,
        disposition: "hostile",
        count: 1
    });

    const chosenToken = Array.isArray(selection) ? selection[0] : selection;
    if (!chosenToken?.actor) return;

    const stats = chosenToken.actor.system;
	const canFinish =
        stats.hp?.value != null &&
        stats.hp.value < 8 &&
        stats.structure?.value == 1;

	const fx = game.modules.get("lancer-weapon-fx")?.api;
	if (!game.modules.get("sequencer")?.active || !fx) {
    ui.notifications.error(
        "BIFURCATE requires Sequencer and Lancer Weapon FX."
    );
    return;
}

	if (!canFinish) {
    const source = reactorToken.object ?? reactorToken;
    const target = chosenToken.object ?? chosenToken;

    const sourcePosition = { x: source.center.x, y: source.center.y };
    const targetPosition = { x: target.center.x, y: target.center.y };
    const targetSize = target.w;

    const ignoreFog = fx.isEffectIgnoreFogOfWar();
    const ignoreLighting = fx.isEffectIgnoreLightingColoration();

    // Check actual animation availability instead of a premium module ID.
    const availableBarrels = [
        "jb2a.barrel.toss.metal.01.01.red",
        "jb2a.barrel.toss.metal.01.01.green"
    ].filter(path => {
        try {
            const entry = Sequencer.Database.getEntry(path);
            return Array.isArray(entry) ? entry.length > 0 : !!entry;
        } catch {
            return false;
        }
    });

    const attack = new Sequence();

    if (availableBarrels.length > 0) {
    const barrel = availableBarrels[
        Math.floor(Math.random() * availableBarrels.length)
    ];
    const pipeSound = "assets/metal-pipe-falling-sound-effect.mp3";

    await Sequencer.Preloader.preloadForClients([barrel, pipeSound]);

    attack.effect()
        .file(barrel)
        .atLocation(sourcePosition)
        .moveTowards(targetPosition)
        .xray(ignoreFog)
        .aboveInterface(ignoreLighting)
        .waitUntilFinished();

    attack.sound()
        .file(pipeSound)
        .volume(fx.getEffectVolume(0.8))
        .waitUntilFinished();

} else {
        // Your default melee animation, using LA's selected tokens.
        const slash = "jb2a.melee_generic.slash.01.orange";
        const swing = "modules/lancer-weapon-fx/soundfx/bladeswing.ogg";
        const hit = "modules/lancer-weapon-fx/soundfx/bladehit.ogg";
        const sparks = "jb2a.static_electricity.03.blue";

        await Sequencer.Preloader.preloadForClients([
            slash, swing, hit, sparks
        ]);

        attack.effect()
            .file(slash)
            .atLocation(sourcePosition)
            .spriteOffset({ x: -0.2 }, { gridUnits: true })
            .stretchTo(targetPosition)
            .xray(ignoreFog)
            .aboveInterface(ignoreLighting)
            .delay(500);

        attack.sound()
            .file(swing)
            .volume(fx.getEffectVolume(0.7))
            .delay(500)
            .waitUntilFinished(-1300);

        attack.sound()
            .file(hit)
            .volume(fx.getEffectVolume(0.7));

        attack.effect()
            .file(sparks)
            .atLocation(targetPosition, {
                randomOffset: 0.8,
                gridUnits: true
            })
            .size(targetSize * 0.5)
            .xray(ignoreFog)
            .aboveInterface(ignoreLighting)
            .repeats(2, 80)
            .waitUntilFinished();
    }

    await api.executeDamageRoll(
        reactorToken,
        [chosenToken],
        1,
        "kinetic",
        "BIFURCATE",
        { paracausal: false }
    );

    await attack.play();

    // Prevent the 7-burn finisher from also running.
    return;
}
    // CUSTOMIZATION — all times are milliseconds.
    const SWORD_START = 500;
    const SWORD_INTERVAL = 250;
    const SWORD_ANGLES = [0, 145, -75, 70, 180];

    const CLAW_GAP_MIN = 350;
    const CLAW_GAP_MAX = 450;
    const CLAW_MAX_DURATION = 800;
    const FADE_OUT = 250;

    const databasePaths = {
        claws: "jb2a.claws.400px.red",
        sword: "jb2a.melee_attack.01.magic_sword.yellow",
        clawImpact: "jb2a.impact.blue.2",
        swordImpact: "jb2a.impact.blue.3",
        sparks: "jb2a.static_electricity.03"
    };

    const swingSound = "modules/lancer-weapon-fx/soundfx/Axe_swing.ogg";
    const hitSound = "modules/lancer-weapon-fx/soundfx/Melee.ogg";

    const random = (min, max) => min + Math.random() * (max - min);

    // Resolve each database entry once so we measure and play the same file.
    function resolveFile(path) {
        let entry = Sequencer.Database.getEntry(path);
        if (Array.isArray(entry)) entry = entry[0];

        const file = entry?.getFile();
        if (typeof file !== "string") {
            throw new Error(`Cannot resolve animation: ${path}`);
        }
        return file;
    }

    function getVideoDuration(file) {
        return new Promise((resolve, reject) => {
            const video = document.createElement("video");
            video.preload = "metadata";

            const timeout = setTimeout(
                () => finish(new Error(`Timed out loading: ${file}`)),
                15000
            );

            function finish(error) {
                const duration = video.duration * 1000;

                clearTimeout(timeout);
                video.onloadedmetadata = null;
                video.onerror = null;
                video.removeAttribute("src");
                video.load();

                if (error) reject(error);
                else if (!Number.isFinite(duration) || duration <= 0) {
                    reject(new Error(`Cannot read animation duration: ${file}`));
                } else {
                    resolve(duration);
                }
            }

            video.onloadedmetadata = () => finish();
            video.onerror = () => finish(
                new Error(`Cannot load animation: ${file}`)
            );
            video.src = file;
        });
    }

    let clips;

    try {
        clips = Object.fromEntries(await Promise.all(
            Object.entries(databasePaths).map(async ([key, path]) => {
                const file = resolveFile(path);
                const duration = await getVideoDuration(file);
                return [key, { file, duration }];
            })
        ));

        await Sequencer.Preloader.preloadForClients([
            ...Object.values(clips).map(clip => clip.file),
            swingSound,
            hitSound
        ]);
    } catch (error) {
        console.error("BIFURCATE:", error);
        ui.notifications.error(error.message);
        return;
    }

    // Save positions before damage, in case damage removes the target.
    const source = reactorToken.object ?? reactorToken;
    const target = chosenToken.object ?? chosenToken;

    const sourcePosition = { x: source.center.x, y: source.center.y };
    const targetPosition = { x: target.center.x, y: target.center.y };
    const targetSize = target.w;
    const sourceSize = source.w;

    const totalDuration =
        SWORD_START +
        (SWORD_ANGLES.length - 1) * SWORD_INTERVAL +
        clips.sword.duration;

    const sequence = new Sequence();
    const ignoreFog = fx.isEffectIgnoreFogOfWar();
    const ignoreLighting = fx.isEffectIgnoreLightingColoration();

    function addEffect(clip, time, position, duration) {
        return sequence.effect()
            .file(clip.file)
            .atLocation(position)
            .delay(time)
            .duration(duration)
            .xray(ignoreFog)
            .aboveInterface(ignoreLighting);
    }

    function addAccent(clip, time, position, size) {
        const duration = Math.min(clip.duration, totalDuration - time);

        return addEffect(clip, time, position, duration)
            .size(size)
            .fadeOut(Math.min(FADE_OUT, duration / 2));
    }

    function addSound(file, time, volume) {
        sequence.sound()
            .file(file)
            .delay(time)
            // Trim any audio tail at the end of the finisher.
            .endTime(totalDuration - time)
            .fadeOutAudio(100)
            .volume(fx.getEffectVolume(volume));
    }

    // Claws remain on the target.
    // The final claw is placed so its fade ends with the final sword.
    const clawDuration = Math.min(
        clips.claws.duration,
        CLAW_MAX_DURATION,
        totalDuration
    );

    const finalClawStart = totalDuration - clawDuration;
    const clawTimes = [];

    for (
        let time = 0;
        time <= finalClawStart - CLAW_GAP_MIN;
        time += random(CLAW_GAP_MIN, CLAW_GAP_MAX)
    ) {
        clawTimes.push(time);
    }

    clawTimes.push(finalClawStart);

    for (const time of clawTimes) {
        const position = {
            x: targetPosition.x + random(-0.18, 0.18) * targetSize,
            y: targetPosition.y + random(-0.18, 0.18) * targetSize
        };

        addEffect(clips.claws, time, position, clawDuration)
            .tint("#720d87")
            .scale(random(0.7, 0.9))
            .rotate(random(0, 360))
            .opacity(0.6)
            .fadeIn(50)
            .fadeOut(Math.min(FADE_OUT, clawDuration / 2))
            .zIndex(1);

        addAccent(clips.clawImpact, time, position, targetSize)
            .tint("#c91af9")
            .opacity(0.65);

        addSound(hitSound, time, 0.3);
    }

    // All five swords originate at the reactor token.
    for (let i = 0; i < SWORD_ANGLES.length; i++) {
        const time = SWORD_START + i * SWORD_INTERVAL;

        addEffect(
            clips.sword,
            time,
            sourcePosition,
            clips.sword.duration
        )
            .size(sourceSize * 6)
            .filter("ColorMatrix", { hue: 180 })
            .moveTowards(targetPosition)
            .spriteRotation(SWORD_ANGLES[i])
            .zIndex(2);

        addSound(swingSound, time, 0.5);

        // Adjustable visual contact point within each sword clip.
        const impactTime = time + clips.sword.duration * 0.5;

        addAccent(
            clips.swordImpact,
            impactTime,
            targetPosition,
            targetSize * 2
        ).tint("#c91af9");

        addAccent(
            clips.sparks,
            impactTime,
            {
                x: targetPosition.x + random(-0.4, 0.4) * targetSize,
                y: targetPosition.y + random(-0.4, 0.4) * targetSize
            },
            targetSize
        ).opacity(0.8);

        addSound(hitSound, impactTime, 0.6);
    }

    // Apply damage once, then start the complete animation.
    await api.executeDamageRoll(
        reactorToken,
        [chosenToken],
        7,
        "burn",
        "BIFURCATE",
        { paracausal: true }
    );

    sequence.wait(totalDuration);
    await sequence.play();
    await api.activateGeneralAction(reactorToken, "Boost")

}

reactions.evaluate:
function (triggerType, triggerData, reactorToken, item, activationName, api) {
            const bonuses = api.getConstantBonuses(reactorToken.actor);
            return !bonuses.some(b => b.id === "bruteStrength_${reactorToken.actor.id}");
}

reactions.activationCode:
async function (triggerType, triggerData, reactorToken, item, activationName, api) {
    await api.addConstantBonus(reactorToken.actor, {
        id: "bruteStrength_${reactorToken.actor.id}",
        name: "Brute Strength",
        val: 1, type: "accuracy", rollTypes: ["hull"]
    });
}

async function (triggerType, triggerData, reactorToken, item, activationName, api) {
            await api.removeConstantBonus(reactorToken.actor, "bruteStrength_${reactorToken.actor.id}");
}

reactions.evaluate:
function (triggerType, triggerData, reactorToken, item, activationName, api) {
    if (!api.inDangerZone(reactorToken)) {return false;}
    if (triggerType == "onInitTechAttack") {
        return true;
    };
    return !String(triggerData.weapon.system.active_profile.type).toLowerCase() == "melee";
}

reactions.activationCode:
function (triggerType, triggerData, reactorToken, item, activationName, api) {
    if (triggerType == "onInitTechAttack") {
        triggerData.cancelTechAttack("${reactorToken.name} is currently on all fours.")
    }
    triggerData.cancelAttack("${reactorToken.name} is currently on all fours.")
}

async function (triggerType, triggerData, reactorToken, item, activationName, api) {
    const targetedToken = triggerData.hitTokens[0]
    await api.applyEffectsToTokens({
    tokens: [targetedToken],
    effectNames: "lancer.statusIconsNames.immobilized",
    duration: {
        label: "end",
        turns: 1,
        rounds: 0,
        overrideTurnOriginId: targetedToken.id
    }
});
}
